begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);grant all on tap_results to authenticated;
create temporary table saved(name text primary key,data jsonb);grant all on saved to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('93000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'session_id',pg_temp.i(n),'role','authenticated','is_anonymous',false)::text,true)$$;
create function pg_temp.ctx() returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101),'productId',pg_temp.i(301),'unitId',pg_temp.i(401))$$;
create function pg_temp.req(n integer default 701) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(n),'expectedPriceVersion',1,'price',140,'cost',null,'baseUnit','liter','unitName','Milliliter','factor','0.001','reason','TEST checked physical selling unit','confirmed',true)$$;
set local role authenticated;select pg_temp.login(12);
select pg_temp.login(11);
reset role;
set local role authenticated;select pg_temp.login(11);
reset role;
select line from tap_results;select * from finish();rollback;
