insert into auth.users(id,email) select pg_temp.i(n),'review-'||n||'@example.invalid' from generate_series(11,12)n;
insert into auth.sessions(id,user_id) select pg_temp.i(n),pg_temp.i(n) from generate_series(11,12)n;
insert into public.organizations(id,name) values(pg_temp.i(1),'TEST review shop');
insert into public.branches(id,organization_id,name,code) values(pg_temp.i(101),pg_temp.i(1),'TEST Magpet','T1'),(pg_temp.i(102),pg_temp.i(1),'TEST Other','T2');
insert into public.staff_memberships(organization_id,user_id,branch_id,role,name) values(pg_temp.i(1),pg_temp.i(11),null,'owner','Owner'),(pg_temp.i(1),pg_temp.i(12),pg_temp.i(101),'cashier','Cashier');
insert into public.products(id,organization_id,name,sku,base_unit,setup_pending,cost_pending,catalog_source,source_stock) values(pg_temp.i(301),pg_temp.i(1),'TEST measured liquid','TEST-ML','piece',true,true,'TEST source',jsonb_build_object('branchId',pg_temp.i(101),'quantity','1000','pending',true,'sha256',repeat('a',64),'asOf','2026-10-22','file','TEST.pdf','page',1));
insert into public.product_units(id,organization_id,product_id,name,factor) values(pg_temp.i(401),pg_temp.i(1),pg_temp.i(301),'Unconfirmed',1);
insert into public.unit_prices values(pg_temp.i(1),pg_temp.i(401),1,140,0,now());
insert into tap_results select throws_ok($$select public.agri_command('product_review_state',pg_temp.ctx())$$,'42501','Only the owner can review imported products','Cashiers cannot access owner review operations');
insert into tap_results select throws_ok($$select public.agri_command('review_import_setup',pg_temp.req())$$,'42501','Only the owner can review imported products','Cashier cannot change units');
insert into tap_results select is(public.agri_command('product_review_state',pg_temp.ctx())->>'stock','0','Source quantity is not usable stock');
insert into tap_results select is(public.agri_command('product_review_state',pg_temp.ctx())->'sourceStock'->>'quantity','1000','Source evidence retained separately');
insert into tap_results select is(public.agri_command('snapshot',pg_temp.ctx())->'products'->0->'sourceStock'->>'quantity','1000','Snapshot carries structured source evidence');
insert into tap_results select is(public.agri_command('snapshot',pg_temp.ctx()||jsonb_build_object('branchId',pg_temp.i(102)))->'products'->0->'sourceStock','null'::jsonb,'Source stock is scoped to its actual branch');
insert into tap_results select throws_ok($$select public.agri_command('review_import_setup',pg_temp.req()||'{"confirmed":false}')$$,'P0001','Confirm the reviewed values and enter a reason','Explicit review required');
insert into tap_results select lives_ok($$select public.agri_command('review_import_setup',pg_temp.req())$$,'Owner confirms measured unit without inventing cost');
insert into tap_results select is(public.agri_command('review_import_setup',pg_temp.req())->>'duplicate','true','Same setup request is idempotent');
insert into tap_results select throws_ok($$select public.agri_command('review_import_setup',pg_temp.req()||'{"price":141}')$$,'P0001','This request reference belongs to different reviewed values','Request cannot be reused for different money');
insert into tap_results select is((select base_unit from public.products where id=pg_temp.i(301)),'liter','Stock base unit confirmed');
insert into tap_results select ok((select cost_pending from public.products where id=pg_temp.i(301)),'Blank cost remains explicitly unknown');
insert into tap_results select is((select count(*)::int from public.unit_prices where unit_id=pg_temp.i(401)),2,'Exactly one new immutable price version');
insert into tap_results select is((select factor from public.product_units where id=pg_temp.i(401)),0.001::numeric,'mL conversion exact');
insert into tap_results select is((select count(*)::int from public.inventory_movements),0,'Unit confirmation never posts stock');
insert into public.inventory_movements(organization_id,branch_id,product_id,quantity,kind,source_id,created_by) values(pg_temp.i(1),pg_temp.i(101),pg_temp.i(301),0.1,'adjustment',pg_temp.i(702),pg_temp.i(11));
insert into saved values('stock',pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(703),'expectedPriceVersion',2,'expectedStock','0.1','expectedRevision',(select max(id)::text from public.inventory_movements),'quantity','1000','sourceHash',repeat('a',64),'reason','TEST verified current balance','confirmed',true));
insert into tap_results select throws_ok($$select public.agri_command('confirm_import_stock',(select data from saved where name='stock')||'{"expectedStock":"0"}')$$,'P0001','Stock changed. Refresh and review the balance again','Stale stock cannot overwrite a newer movement');
insert into tap_results select throws_ok($$select public.agri_command('confirm_import_stock',(select data from saved where name='stock')||'{"sourceHash":"wrong"}')$$,'P0001','The source evidence changed. Refresh before posting stock','Evidence mismatch blocked');
insert into tap_results select lives_ok($$select public.agri_command('confirm_import_stock',(select data from saved where name='stock'))$$,'Reviewed final stock posts separately');
insert into tap_results select is(public.agri_command('confirm_import_stock',(select data from saved where name='stock'))->>'duplicate','true','Retry cannot add stock again');
insert into tap_results select is(public.agri_command('product_review_state',pg_temp.ctx())->>'stock','1.000000','Final balance is 1 L, not old stock plus 1 L');
insert into tap_results select is(public.agri_command('product_review_state',pg_temp.ctx())->'sourceStock'->>'quantity','1000','Posting retains original source quantity');
insert into tap_results select is(public.agri_command('product_review_state',pg_temp.ctx())->'sourceStock'->>'pending','false','Unposted status clears only after explicit stock action');
insert into tap_results select throws_ok($$select public.agri_command('confirm_import_stock',(select data from saved where name='stock')||jsonb_build_object('requestId',pg_temp.i(704)))$$,'P0001','Confirm the unit first and choose an unposted source balance','A fresh request cannot repost completed source stock');
insert into tap_results select lives_ok($$select public.agri_command('review_product_price',pg_temp.req(705)||'{"expectedPriceVersion":2,"price":145,"cost":110}')$$,'Price and actual cost can change after stock history exists');
insert into tap_results select throws_ok($$select public.agri_command('review_product_price',pg_temp.req(706)||'{"expectedPriceVersion":2,"price":149}')$$,'P0001','The selling unit or price changed. Refresh and review it again','Concurrent price changes cannot overwrite a newer version');
insert into tap_results select ok(not (select cost_pending from public.products where id=pg_temp.i(301)),'Actual confirmed cost clears its own pending state');
insert into tap_results select is((select count(*)::int from public.unit_prices where unit_id=pg_temp.i(401)),3,'Original and both reviewed price versions retained');
insert into tap_results select is((select price from public.unit_prices where unit_id=pg_temp.i(401) and version=1),140::bigint,'Original price unchanged');
insert into tap_results select is((select quantity from public.inventory_movements where source_id=pg_temp.i(703)),0.9::numeric,'Journal records only reviewed difference');
insert into tap_results select is((select count(*)::int from public.payments),0,'Review actions never create cash movements');
insert into tap_results select is((select count(*)::int from public.sales),0,'Review actions never create sales');
